python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx',data_only=False)
ws=wb['Data']
# search for year labels 2018-2022 in first 100 rows and 50 cols
years={2018,2019,2020,2021,2022,'2018','2019','2020','2021','2022'}
hits=[]
for r in range(1,101):
    for c in range(1,51):
        v=ws.cell(row=r,column=c).value
        if v in years:
            hits.append((r,c,v))
if not hits:
    print('No year labels found in A1:AX100')
else:
    for r,c,v in hits:
        print(f'Found {v} at {get_column_letter(c)}{r}')
# also show row/col labels around data table
print('Data dimensions max_row',ws.max_row,'max_col',ws.max_column)
# print first 5 rows/15 cols non-empty
for r in range(1,26):
    row=[]
    for c in range(1,16):
        v=ws.cell(row=r,column=c).value
        row.append('' if v is None else str(v))
    if any(row):
        print(f'r{r}:\t'+ '\t'.join(row))
